import json,re
a=json.load(open('wwo/input/g8.json'))
F={
"platform-participant-email-warnings":({"outcome":"Organisers see at a glance which participants have a placeholder, missing or undeliverable email before booking meetings with them."},"outcome added 'sending messages', which no story mentions; EP-12726/EP-14907 are about meeting booking and warnings"),
"platform-profile-and-page-access-2023q1":({"benefit":"Search options in profile select fields and control public file page access with the sign-in setting."},"benefit claimed 'faster' with no evidence; EP-12583 adds search only"),
"platform-admin-panel-guidance":({"why":"Some admin setting names were confusing, and clients needed clearer names, descriptions and page explanations."},"why attributed a complaint to clients; EP-15967 only lists confusing setting names to be understood easily"),
"platform-inactive-account-activation":({"outcome":"Users who missed their activation email can resend it straight from the login screen, on web or in the app."},"outcome 'without contacting support' not in any story (EP-17488, EP-15585)"),
"platform-search-performance-2023":({"detail":"Search indexing after event cloning waits until the clone has finished, whole-event indexing runs in bulk, exhibitor list requests on the marketplace page were reorganised, and participant company, job title and news author were added to search.","outcome":"Attendees get a quicker marketplace list view and can search people by company or job title, and cloned events sync to search once cloning is complete."},"detail said clone indexing runs in bulk (EP-13513 delays it) and called search indexes 'database indexes' (EP-18427); outcome 'ready sooner after an event is set up' overstated"),
"platform-admin-mfa":({"what":"Admin accounts have an MFA tab to enable authenticator-app login for admins, exclude chosen admins, and send MFA setup emails one at a time or in bulk."},"what said organisers enable it; EP-11695 makes the tab visible to super admins and chosen admins"),
"platform-module-permission-alignment":({"outcome":"Organisers set meeting and message permissions for each user type in one place instead of splitting them across two settings pages."},"outcome 'trust that settings apply everywhere' overstated; EP-16638 moves permissions into one place"),
"platform-floor-plan-performance":({"title":"Floor plan and filter optimisation","benefit":"Integrated floor plans are cached, and the filters used by the mobile apps put less load on the database.","outcome":"Repeated floor plan and filter requests from the apps put less load on the platform."},"'faster', 'respond faster' and 'busy event days' have no evidence; EP-21993 is about database load, EP-22678/EP-18599 have no text"),
"platform-badge-scan-login":({"why":"Attendees at the event need a quick way into the app using the badge they already carry."},"implied why claimed email and password typing is slow, but the MVP is the one-time password flow (EP-19419)"),
"platform-otp-login-improvement":({"benefit":"Let users on public events request a one-time login code whatever their account status.","detail":"On public events, a one-time code is emailed on request whatever the account status, and inactive users become active once they log in.","what":"On public events, a one-time code is emailed on request whatever the account status, and inactive users become active once they sign in with it.","why":"Users need to sign in with a code even before their account has been activated."},"EP-18110 MVP covers public events only (private events 'nice to have'); implied why claimed a past failure"),
"platform-admin-workflow-2024q1":({"benefit":"Open a user’s profile as them, keep list filters between visits and find session settings more easily."},"'faster' for session settings unsupported; EP-23885 regroups the page for clarity"),
"platform-reliable-exports":({"outcome":"Organisers get their export file even after a temporary glitch, without having to start it again."},"'asking for help' not in EP-16797/EP-1094"),
"platform-admin-colours":({"why":"The admin panel needed new primary and secondary colours."},"EP-28362 has no text; 'current colour scheme' was invented"),
"platform-account-switcher":({"outcome":"Users move between their own, team member, parent and child company accounts from a dropdown on desktop and mobile web."},"'a couple of clicks' is an unsupported count; EP-28676 says a dropdown"),
"platform-otp-whatsapp-sms":({"outcome":"Attendees can get their login code by message on their phone as well as by email, and organisers choose which channels to offer."},"'the channel they check most' unsupported; EP-26859 sends through every enabled channel, users do not choose"),
"platform-admin-panel-2024q4":({"detail":"Redundant settings were removed, admin tables show empty states, and the retired hospitality module, table section tax fields and exhibitor manual payment setting are hidden."},"detail said these modules 'can be hidden' (an option); EP-28153 hides retired items for everyone"),
"platform-australia-hosting":({"title":"Australian cloud region","benefit":"Platform queues, data tables and log groups are set up in an Australian cloud region.","detail":"Cloud resources, including queues, data tables and log groups, were set up in an Australian region.","why":"Events in Australia may need platform services located in the region.","outcome":"The platform has queues, data tables and log groups ready in an Australian region."},"EP-35819 only creates queues, DynamoDB tables and log groups; hosting whole event platforms there is not shown"),
"platform-security-hardening-2024q4":({"outcome":"Activation codes are tied to the account they belong to, and badge scan requests must carry a valid signed token."},"EP-34239 says the change is a hope to fix duplicates, not confirmed unique codes; 'only trusted apps' overstated for EP-35880"),
"platform-sign-in-profile-2024q4":({"benefit":"See clearer profile titles and error codes, and let admins sign in as users on the new frontend.","detail":"The profile edit page title reflects the account type, the frontend shows error codes, the sign-up prompt is hidden in the login window when registration is off, and admins can log in as a user on the new frontend by token.","what":"The profile edit page title reflects the account type, the frontend shows error codes, the sign-up prompt is hidden when registration is off, and admins can log in as a user on the new frontend by token."},"EP-37093 is the customer service (admin log in as user) token login, not custom login services; EP-36297 hides the sign-up line only when registration is off"),
"platform-buttons-validation-2025q1":({"why":"Users need the main action to look the same on every page, and an error for a too-short entry that says clearly what is wrong."},"implied why claimed a past inconsistency not stated in EP-38372/EP-37692"),
"platform-attendee-onboarding":({"outcome":"Attendees pick their interests when they first sign in and are told when their recommendations are ready, and organisers decide how strongly to prompt them."},"'relevant recommendations from their first visit' overstated; EP-40531 notifies after recalculation"),
"platform-performance-security-2025q2":({"benefit":"Long option lists load on demand, and app visitor requests carry fewer parameters for the database to check.","detail":"Additional database indexes were added, multi-select fields with many options load on demand, and token and identifier parameters were removed from app visitor requests.","outcome":"Users can open fields with long option lists without waiting for every option to load, and app people listings trigger fewer database checks."},"EP-43090 removed parameters from app visitor requests to cut database checks, not to protect sensitive data; 'faster' unevidenced"),
"platform-admin-safeguards-2025q3":({"detail":"Admins confirm participant category changes after a warning that they may affect access, visibility and matchmaking. Region values are validated, and the save and cancel bar has a blurred background."},"'for readability' not in EP-43097"),
"platform-performance-2025q4":({"title":"Fewer app requests, lighter search","benefit":"The app sends fewer calls to the server and delegate search returns lighter responses.","outcome":"The platform carries less load from repeated app requests, and delegate search sends back only the data it needs."},"'quicker app' and 'stays responsive when many attendees use it' unevidenced; EP-45987 is about server overload"),
"platform-locale-dates-translations":({"outcome":"Attendees read dates in the format they are used to and meet fewer untranslated terms in their language."},"'fully in their language' overstated; EP-46955 still lists absent translations"),
"platform-performance-2026q2":({"benefit":"Pages send fewer unnecessary requests, and profile download buttons show when a file is on its way.","why":"The site repeated the same empty banner request on every navigation and made sign-in checks with no token, adding needless calls to the server."},"'faster page loads' unevidenced; EP-49453 is about calls with a null token, not page changes"),
"platform-performance-2026q3":({"outcome":"Attendees get pages and images that load faster with less data used."},"'especially on mobile connections' not in EP-57489/EP-57336"),
"platform-selective-cloning":({"benefit":"Choose whether sponsors, news, sessions, local categories and floor plan carry over when you clone an event.","detail":"The clone dialog offers separate checkboxes for sponsors, news, sessions, local categories and floor plan.","what":"The clone dialog offers separate checkboxes for sponsors, news, sessions, local categories and floor plan, with a confirmation summary, so only selected content is copied."},"EP-52816 covers those five categories only; 'exactly which content' and 'other content categories' overstated"),
}
out=[]
for r in a:
    if r['id'] in F:
        f,why=F[r['id']];out.append({"id":r['id'],"verdict":"fix","fix":f,"reason":why})
    else:
        out.append({"id":r['id'],"verdict":"ok","fix":{},"reason":"supported by the source stories"})
assert set(F)<=set(x['id'] for x in a)
L={'what':240,'why':220,'outcome':220,'benefit':160,'detail':400}
bad=re.compile(r'—|–|organiz|color|favorit|optimiz|seamless|powerful|revolution|game-chang|effortless|cutting-edge|EP-\d',re.I)
ids=[x['id'] for x in out]; assert len(ids)==len(set(ids))==len(a)
for x in out:
    for k,v in x['fix'].items():
        if k in L: assert len(v)<=L[k],(x['id'],k,len(v))
        if k=='title': assert 2<=len(v.split())<=6,(x['id'],v)
        assert not bad.search(v),(x['id'],k)
json.dump(out,open('wwo/g8_v/verdicts.json','w'),ensure_ascii=False,indent=1)
print(len(out),sum(x['verdict']=='fix' for x in out))
